solutionCode:
pub fn o_aviso_da(caixa: Option<i32>) -> String {
    match caixa {
        Some(v) => format!("veio: {}", v),
        None => String::from("nao veio"),
    }
}

pub fn o_leite_de(leite: i32) -> Option<i32> {
    if leite > 0 {
        Some(leite * 2)
    } else {
        None
    }
}

testsCode:
use desafio::o_aviso_da;
use desafio::o_leite_de;

#[test]
fn testa_o_aviso_da_caixa_cheia_do_leite_tres() {
    assert_eq!(o_aviso_da(o_leite_de(3)), String::from("veio: 6"));
}

#[test]
fn testa_o_aviso_da_caixa_vazia_do_leite_negativo() {
    assert_eq!(o_aviso_da(o_leite_de(-1)), String::from("nao veio"));
}
